import express from "express";
import { createServer } from "node:http";
import { Server } from "socket.io";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { resolveTiming } from "./shared/domain/economy/jade-loop.js";
import { wireServer } from "./server/boot/wire-server.js";
import { createTestHooks } from "./server/shell/test-hooks.js";
import { loadRuntimeConfig } from "./server/config/runtime-config.js";
import { createLogger } from "./server/observability/logger.js";
import { createMetrics } from "./server/observability/metrics.js";
import { createRuntimeHealth } from "./server/observability/runtime-health.js";
import { installHttpSecurity } from "./server/security/http-security.js";
import {
  installSocketServerSecurity,
  socketServerOptions
} from "./server/security/socket-security.js";

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

const runtimeConfig = loadRuntimeConfig();
const logger = createLogger(runtimeConfig);
const metrics = createMetrics();
const health = createRuntimeHealth();
const app = express();
const httpServer = createServer(app);
const io = new Server(httpServer, socketServerOptions(runtimeConfig));
const PORT = runtimeConfig.port;
const OPEN_WINDOW_RATE = 0.04;
const DEFAULT_AUCTION_HALL_ID = "novice";
const TIMING_PROFILE = process.env.JADE_TIMING_PROFILE || "normal";
const TIMING = resolveTiming(TIMING_PROFILE);

installHttpSecurity({ app, config: runtimeConfig, logger, metrics, health });
const stopSocketSecurity = installSocketServerSecurity({ io, config: runtimeConfig, logger, metrics });
app.use(express.json({ limit: "32kb", strict: true }));
app.use(express.static(path.join(__dirname, "public"), {
  etag: true,
  maxAge: 0,
  setHeaders(res, filePath) {
    if (/\.(?:png|jpe?g|webp|gif|svg)$/i.test(filePath)) {
      res.setHeader("Cache-Control", "public, max-age=3600, must-revalidate");
      return;
    }
    res.setHeader("Cache-Control", "no-cache");
  }
}));
// Isomorphic domain rules — browsable at /shared/* (same files Node imports)
app.use("/shared", express.static(path.join(__dirname, "shared")));

const boot = wireServer({
  app,
  io,
  httpServer,
  PORT,
  TIMING,
  TIMING_PROFILE,
  OPEN_WINDOW_RATE,
  DEFAULT_AUCTION_HALL_ID,
  runtimeConfig,
  logger,
  metrics,
  health,
  stopSocketSecurity
});

export const { materialCatalogForPlayer, buyMaterialPack } = boot;
export const __testHooks = createTestHooks(boot.testHookBindings);

function isDirectRun() {
  return Boolean(process.argv[1]) && path.resolve(process.argv[1]) === __filename;
}

if (isDirectRun()) {
  boot.startServer().catch((error) => {
    health.markError(error);
    logger.fatal({ error: error?.message || error }, "server startup failed");
    process.exitCode = 1;
  });
}

